"""Matrix of exception types x data types x use_memory_fs.

Run as:  python exc_matrix.py <memfs:none|false> <exc_name> <op_name>
Prints one line: RESULT <status> <detail>
"""
import sys
import traceback

import numpy as np
import pandas as pd

from pandarallel import pandarallel


class CustomError(Exception):
    pass


class UnpicklableError(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.lock = lambda x: x  # lambda -> not picklable by pickle


EXCS = {
    "RuntimeError": RuntimeError("boom-runtime"),
    "AttributeError": AttributeError("boom-attr"),
    "ZeroDivisionError": None,  # raised naturally
    "KeyboardInterrupt": KeyboardInterrupt(),
    "SystemExit": SystemExit(3),
    "CustomError": CustomError("boom-custom"),
    "UnpicklableError": None,
}


def make_udf(exc_name):
    if exc_name == "ZeroDivisionError":
        def f(x, *a, **k):
            return 1 / 0
    elif exc_name == "UnpicklableError":
        def f(x, *a, **k):
            raise UnpicklableError("boom-unpicklable")
    else:
        exc = EXCS[exc_name]

        def f(x, *a, **k):
            raise exc
    return f


def build(op, size):
    df = pd.DataFrame({"a": np.arange(size), "b": np.arange(size) * 2,
                       "g": np.arange(size) % 3})
    return df


def run_op(op, df, f, parallel):
    suffix = "parallel_" if parallel else ""
    if op == "df_apply_axis1":
        return getattr(df, suffix + "apply")(f, axis=1)
    if op == "df_apply_axis0":
        return getattr(df, suffix + "apply")(f, axis=0)
    if op == "df_applymap":
        if parallel:
            return df.parallel_applymap(f)
        return df.applymap(f)
    if op == "series_apply":
        return getattr(df.a, suffix + "apply")(f)
    if op == "series_map":
        return getattr(df.a, suffix + "map")(f)
    if op == "groupby_apply":
        return getattr(df.groupby("g"), suffix + "apply")(f)
    if op == "groupby_col_apply":
        return getattr(df.groupby("g").a, suffix + "apply")(f)
    if op == "rolling_apply":
        return getattr(df.a.rolling(2), suffix + "apply")(f, raw=True)
    if op == "expanding_apply":
        return getattr(df.a.expanding(), suffix + "apply")(f, raw=True)
    if op == "groupby_rolling":
        return getattr(df.groupby("g").a.rolling(2), suffix + "apply")(f, raw=True)
    if op == "groupby_expanding":
        return getattr(df.groupby("g").a.expanding(), suffix + "apply")(f, raw=True)
    raise ValueError(op)


def main():
    memfs_arg, exc_name, op = sys.argv[1], sys.argv[2], sys.argv[3]
    use_memory_fs = None if memfs_arg == "none" else False
    pandarallel.initialize(nb_workers=2, progress_bar=False,
                           use_memory_fs=use_memory_fs, verbose=0)
    df = build(op, 12)
    f = make_udf(exc_name)

    # sequential reference
    seq_type = None
    try:
        run_op(op, df, f, parallel=False)
        seq_type = "NO_EXCEPTION"
    except BaseException as e:  # noqa
        seq_type = type(e).__name__

    try:
        run_op(op, df, f, parallel=True)
        print(f"RESULT seq={seq_type} par=NO_EXCEPTION")
    except BaseException as e:  # noqa
        print(f"RESULT seq={seq_type} par={type(e).__name__} msg={str(e)[:160]!r}")


if __name__ == "__main__":
    main()

