import sys
import numpy as np
import pandas as pd
from pandarallel import pandarallel
from myexc import CustomError, UnpicklableError

memfs_arg, which, op = sys.argv[1], sys.argv[2], sys.argv[3]
use_memory_fs = None if memfs_arg == "none" else False


def f_custom(x, *a, **k):
    raise CustomError("boom-custom-module")


def f_unpicklable(x, *a, **k):
    raise UnpicklableError("boom-up")


def f_ki(x, *a, **k):
    raise KeyboardInterrupt()


def f_se(x, *a, **k):
    raise SystemExit(3)


def f_ret_unpicklable(x, *a, **k):
    return lambda y: y


F = {"custom": f_custom, "unpicklable": f_unpicklable, "ki": f_ki,
     "se": f_se, "ret_unpicklable": f_ret_unpicklable}[which]

pandarallel.initialize(nb_workers=2, progress_bar=False,
                       use_memory_fs=use_memory_fs, verbose=0)
df = pd.DataFrame({"a": np.arange(12), "b": np.arange(12) * 2, "g": np.arange(12) % 3})


def run(parallel):
    s = "parallel_" if parallel else ""
    if op == "df_apply_axis1":
        return getattr(df, s + "apply")(F, axis=1)
    if op == "series_apply":
        return getattr(df.a, s + "apply")(F)
    if op == "series_map":
        return getattr(df.a, s + "map")(F)
    if op == "df_applymap":
        return df.parallel_applymap(F) if parallel else df.applymap(F)
    if op == "groupby_apply":
        return getattr(df.groupby("g"), s + "apply")(F)
    if op == "rolling_apply":
        return getattr(df.a.rolling(2), s + "apply")(F, raw=True)
    raise ValueError(op)


try:
    run(False)
    seq = "NO_EXCEPTION"
except BaseException as e:
    seq = type(e).__name__

sys.stdout.write(f"SEQ={seq} ")
sys.stdout.flush()
try:
    r = run(True)
    print(f"PAR=NO_EXCEPTION result_type={type(r).__name__}")
except BaseException as e:
    print(f"PAR={type(e).__name__} msg={str(e)[:200]!r}")
